mapper.select:
SELECT COUNT(1) FROM sys_role_permission rp INNER JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id = #{roleId}
AND p.permission_code LIKE CONCAT('%', #{query.permissionCode}, '%')
AND p.permission_name LIKE CONCAT('%', #{query.permissionName}, '%')
AND p.status = #{query.status}

SELECT p.id, p.permission_code, COALESCE(p.permission_name, p.permission_code) AS permission_name, p.status FROM sys_role_permission rp INNER JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id = #{roleId}
AND p.permission_code LIKE CONCAT('%', #{query.permissionCode}, '%')
AND p.permission_name LIKE CONCAT('%', #{query.permissionName}, '%')
AND p.status = #{query.status}
ORDER BY p.permission_code

SELECT COUNT(1) FROM sys_role_permission rp INNER JOIN sys_role r ON r.id = rp.role_id WHERE rp.permission_id = #{permissionId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}

SELECT r.id, r.role_code, r.role_name, r.status FROM sys_role_permission rp INNER JOIN sys_role r ON r.id = rp.role_id WHERE rp.permission_id = #{permissionId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}
ORDER BY r.role_code
